// Sends a GET request to the JWKS endpoint and deserializes the response body
// into a `Jwks` struct, whose `keys` field is a Vec of returned keys
fn fetch_jwks(client: &Client, base_url: &Url) -> Result<Jwks> {
    let jwks_url = base_url.join("/api/auth/jwks")?;

    let response = client
        .get(jwks_url)
        .send()
        .context("api/auth/jwks endpoint not found")?
        .error_for_status()
        .context("http error returned")?;

    let jwks: Jwks = response.json().context("Invalid JSON in response")?;

    if jwks.keys.is_empty() {
        bail!("No key in JWKSs");
    }

    Ok(jwks)
}

